        // Call Command as owner
        vm.prank(c.Owner());
        bytes memory emptyData = "";
        (bool success, ) = address(c).call{value: commandValue}(abi.encodeWithSelector(c.Command.selector, addr, emptyData));

        // If Command failed, the rule is vacuously true
