            return;
        }

        // Now call multiplicate with the given value
        vm.deal(address(this), multiplicateValue);
        (bool multiSuccess, ) = address(c).call{value: multiplicateValue}(abi.encodeWithSelector(c.multiplicate.selector, caller));

        // The rule: after multiplicate, if it succeeded, the sum of all multiplicate values since last Command shouldn't exceed current balance
