pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address adr, uint256 amount, bytes memory data) public {
        vm.assume(adr != address(c.Owner()));
        vm.assume(adr != address(0));
        vm.assume(data.length > 0);

        uint256 initialBalance = 1 ether;
        vm.deal(address(c), initialBalance);

        // Prepare to call multiplicate via Command
        bytes memory callData = abi.encodeWithSignature("multiplicate(address)", adr);

        // Ensure msg.value >= address(this).balance
        vm.deal(address(this), initialBalance * 2);
        uint256 callValue = initialBalance;
        vm.assume(callValue >= address(c).balance);

        uint256 ownerBalanceBefore = address(c.Owner()).balance;

        // Execute Command with the multiplicate calldata
        (bool success, ) = address(c).call{value: callValue}(abi.encodeWithSignature("Command(address,bytes)", adr, callData));
        vm.assume(success);

        uint256 ownerBalanceAfter = address(c.Owner()).balance;

        // After the call, the contract's balance should be zero (all sent to adr, not Owner)
        assertTrue(address(c).balance == 0);
        // Owner's balance should be unchanged (not receive the funds)
        assertTrue(ownerBalanceAfter == ownerBalanceBefore);
    }
}
